import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const data = JSON.parse(readFileSync(path.join(root, 'lib/seed-data.json'), 'utf8'));
const q = (v) => `'${String(v).replaceAll("'", "''")}'`;

const lines = [
  '-- AUTO-GENERATED by `npm run seed:sql`. Edit lib/seed-data.json instead.',
  '-- Run AFTER sql/01_schema.sql.',
  '',
  'insert into user_settings (user_id, exam_name, study_time, alarm_enabled, alarm_days, snooze_minutes, focus_mode, pomodoro_min, short_break_min, long_break_min, streak_freezes, frozen_dates)',
  "values ('me', 'NORCET', '19:00', true, '[0,1,2,3,4,5,6]'::jsonb, 5, true, 25, 5, 15, 2, '[]'::jsonb)",
  'on conflict (user_id) do update set exam_name = excluded.exam_name;',
  '',
  'insert into user_stats (user_id) values (\'me\') on conflict (user_id) do nothing;',
  '',
  'insert into subjects (user_id, id, code, name, "group", semester, icon, color) values',
  data.subjects
    .map((s) => `  ('me', ${q(s.id)}, ${q(s.code)}, ${q(s.name)}, ${q(s.group)}, ${s.semester}, ${q(s.icon)}, ${q(s.color)})`)
    .join(',\n') + '\non conflict (user_id, code) do update set name = excluded.name, "group" = excluded."group", semester = excluded.semester;',
  '',
  'insert into topics (user_id, id, subject_id, title, level1, level2, level3, revision_count) values',
  data.subjects
    .flatMap((s) => s.topics.map((title, i) => `  ('me', ${q(`t-${s.id}-${i + 1}`)}, ${q(s.id)}, ${q(title)}, 'todo', 'todo', 'todo', 0)`))
    .join(',\n') + '\non conflict (id) do nothing;',
  '',
];

mkdirSync(path.join(root, 'sql'), { recursive: true });
writeFileSync(path.join(root, 'sql/02_seed.sql'), lines.join('\n'));
console.log(`Wrote sql/02_seed.sql — ${data.subjects.length} subjects, ${data.subjects.reduce((n, s) => n + s.topics.length, 0)} topics.`);
